{{-- A text and its marks, the first one outermost, on one line so that no space is added; a link opens another site in a new tab, without telling it where it came from. --}}@php($mark = $marks[0] ?? null)@php($rest = array_slice($marks, 1))@php($href = ($mark['type'] ?? null) === 'link' ? \App\Support\LessonDocument::href($mark['attrs']['href'] ?? null) : null)@if ($mark === null){{ $text }}@elseif ($mark['type'] === 'bold')<strong>@include('filament.school.lesson-text', ['marks' => $rest])</strong>@elseif ($mark['type'] === 'italic')<em>@include('filament.school.lesson-text', ['marks' => $rest])</em>@elseif ($mark['type'] === 'underline')<u>@include('filament.school.lesson-text', ['marks' => $rest])</u>@elseif ($mark['type'] === 'strike')<s>@include('filament.school.lesson-text', ['marks' => $rest])</s>@elseif ($mark['type'] === 'code')<code>@include('filament.school.lesson-text', ['marks' => $rest])</code>@elseif ($mark['type'] === 'subscript')<sub>@include('filament.school.lesson-text', ['marks' => $rest])</sub>@elseif ($mark['type'] === 'superscript')<sup>@include('filament.school.lesson-text', ['marks' => $rest])</sup>@elseif ($href)<a href="{{ $href }}" target="_blank" rel="noopener noreferrer" title="{{ __('pedagogy.external_link') }}">@include('filament.school.lesson-text', ['marks' => $rest]) ↗</a>@else @include('filament.school.lesson-text', ['marks' => $rest])@endif